// Run Once for All Items
const fired = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };
// 支援環境變數覆寫（CLI 執行時指定 preset）
let preset = null;
try { preset = process.env.N8N_SYNC_PRESET || null; } catch (e) {}
if (!preset) {
  preset =
    fired('Manual backfill') ? 'backfill' :
    fired('Manual days90')   ? 'days90'   :
    fired('Manual days30')   ? 'days30'   :
    fired('Cron 90d')        ? 'days90'   : 'days30';
}

const HKT = 8 * 60; // 香港無 DST，固定 +08:00
const today = new Date(Date.now() + HKT * 60000).toISOString().slice(0, 10); // HKT 民曆日
const addDays = (d, n) => new Date(Date.UTC(
  +d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10),
) + n * 86400000).toISOString().slice(0, 10);

const start = preset === 'backfill' ? '2026-08-01' : addDays(today, -1); // 兩者含過去 1 天
const horizon = preset === 'days30' ? 30 : 90;

// 全部用 UTC ISO（'Z'）—— PostgREST 唔接受 URL 內嘅 '+'（會被 encode 成 %2B 而 decode 失敗）
const toUtc = (ymd, hktHour) => {
  // ymd 係 HKT 民曆日；hktHour 係 HKT 時數
  const [y, m, d] = ymd.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d, hktHour - 8, 0, 0)).toISOString();
};

return [{
  json: {
    preset,
    window_days: horizon,
    time_min: toUtc(start, 0),                       // HKT 00:00 → UTC
    time_max: toUtc(addDays(today, horizon), 0),     // HKT 00:00 → UTC
    batch_time: new Date().toISOString(),
  },
}];

// Run Once for All Items
const cfg = $('Config').first().json;
const ACCOUNT = 'personal';

// 1) 錯誤旗標 → abort：唔寫任何嘢（防止 partial fetch 造成錯誤 cleanup）
const f = $('Flags personal');
const flags = f.isExecuted ? f.all().map(i => i.json) : [];
if (flags.length > 0) {
  return [{ json: { outcome: 'error', message: flags.map(x => x.message).join(' | ') } }];
}

// 2) 收 Google 事件，逐 source_calendar 出名（保證 tagging 準確）
const sources = [
  ['primary',     $('Fetch primary').all()],
  ['香港節慶假日', $('Fetch holidays').all()],
  ['家人',        $('Fetch family').all()],
];

function normalize(e, sourceCalendar) {
  const allDay = Boolean(e.start?.date) && !e.start?.dateTime;
  return {
    id: `${ACCOUNT}_${e.id}`,                       // 符合 id check（account_key‖'_'‖google_event_id）
    google_event_id: e.id,
    title: e.summary ?? '',
    description: e.description ?? '',
    start_time: allDay ? `${e.start.date}T00:00:00+08:00` : e.start.dateTime,
    end_time:   allDay ? `${e.end.date}T00:00:00+08:00`   : e.end.dateTime, // end.date 係 exclusive
    is_all_day: allDay,
    location: e.location ?? '',
    account_key: ACCOUNT,
    source_calendar: sourceCalendar,
    relevance: 'context',                            // Phase 3 全部用 default，唔派生 linked/noise
    calendar_status: e.status ?? 'confirmed',
    cancelled_at: null,                              // 寫入的行必然 live（Google 有就係存在）
    last_synced_at: cfg.batch_time,
    _updated: e.updated ?? '',                       // 內部欄位，POST 時剝走
  };
}

const gEvents = [];
const byCalendar = {};
for (const [src, items] of sources) {
  byCalendar[src] = items.length;
  for (const it of items) {
    if (it.json?.id) gEvents.push(normalize(it.json, src));
  }
}

// 3) DB 現狀（分頁 items 攤平；GET 冇 filter cancelled_at，gate 同 diff 共用）
const dbRows = $('DB GET personal').all()
  .flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
const db = new Map(dbRows.map(r => [r.id, r]));

// 4) D3 增量 gate：新事件 / cancelled 重現（無條件重設）/ updated > last_synced_at
const toWrite = gEvents.filter(ev => {
  const d = db.get(ev.id);
  if (!d) return true;                              // INSERT
  if (d.cancelled_at != null) return true;          // 重現 → upsert 帶 cancelled_at:null 重設
  return new Date(ev._updated) > new Date(d.last_synced_at);  // UPDATE；其餘跳過
});

// 5) D2 cleanup diff：DB 窗口內 live ids − Google 返回 ids
const googleIds = new Set(gEvents.map(e => e.id));
const missing = dbRows
  .filter(r => r.cancelled_at == null && !googleIds.has(r.id))
  .map(r => r.id);

// 6) 輸出：rows chunks（500/POST）＋ 一個 cleanup item（missing 同 detail 搭呢件行）
const detail = {
  preset: cfg.preset, window_days: cfg.window_days,
  time_min: cfg.time_min, time_max: cfg.time_max,
  fetched: gEvents.length, by_calendar: byCalendar,
  written: toWrite.length, cancelled: missing.length,
};
const out = [];
for (let i = 0; i < toWrite.length; i += 500) {
  out.push({ json: { rows: toWrite.slice(i, i + 500) } });
}
out.push({ json: { missing, batch_time: cfg.batch_time, detail } });
return out;

// Run Once for All Items — POST 有錯 → 攔住 cleanup（D12 fail-closed）
const mk = $('Marker personal');
if (mk.isExecuted) {
  const msg = mk.all().map(i => i.json?.error?.message ?? 'upsert failed').join(' | ');
  return [{ json: { outcome: 'error', message: msg } }];
}
return $input.all();

// Run Once for All Items — missing ids 切 50/chunk（in.() URL 長度限制）
const ids = $json.missing;
const chunks = [];
for (let i = 0; i < ids.length; i += 50) chunks.push(ids.slice(i, i + 50));
return chunks.map(c => ({
  json: {
    idsIn: 'in.(' + c.map(x => `"${x}"`).join(',') + ')',
    batch_time: $json.batch_time,
  },
}));

// Run Once for All Items — design D5：精準排除，其餘 6 個全讀（含 0 事件）
const out = $input.all().map(i => i.json)
  .filter(c => c?.id && typeof c.summary === 'string')
  .filter(c => c.summary.trim() !== '5. 教師生日')
  .map(c => ({ json: { calendarId: c.id, source_calendar: c.summary.trim() } }));
if (out.length === 0) throw new Error('work calendarList 過濾後 0 個日曆 —— summary 命名或 scope 異常');
return out;

// Run Once for All Items — HTTP response item ↔ calendar item 一一對應（經 pairedItem）
return $input.all().map((item, i) => {
  const cal = $('Filter work calendars').itemMatching(i).json;
  return { json: { ...item.json, source_calendar: cal.source_calendar, _calId: cal.calendarId } };
});
// 註：若某日曆 fetch 出錯，Flags work 已觸發 → Normalize work 會 abort，6→6 對齊前提成立

// Run Once for All Items — flatten Google events response：每個 event 變一個 item，保留 source_calendar / _calId
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  for (const ev of j.items || []) {
    out.push({ json: {
      ...ev,
      source_calendar: j.source_calendar,
      _calId: j._calId,
      ...(j.nextPageToken ? { nextPageToken: j.nextPageToken } : {}),
    } });
  }
}
if (out.length === 0) throw new Error('work events flatten 後 0 個事件');
return out;

// Run Once for All Items
const cfg = $('Config').first().json;
const ACCOUNT = 'work';

// 1) 錯誤旗標 → abort：唔寫任何嘢（防止 partial fetch 造成錯誤 cleanup）
const f = $('Flags work');
const flags = f.isExecuted ? f.all().map(i => i.json) : [];
if (flags.length > 0) {
  return [{ json: { outcome: 'error', message: flags.map(x => x.message).join(' | ') } }];
}

