  const allDay = Boolean(e.start?.date) && !e.start?.dateTime;
  return {
    id: `${ACCOUNT}_${e.id}`,                       // 符合 id check（account_key‖'_'‖google_event_id）
    google_event_id: e.id,
    title: e.summary ?? '',
    description: e.description ?? '',
    start_time: allDay ? `${e.start.date}T00:00:00+08:00` : e.start.dateTime,
    end_time:   allDay ? `${e.end.date}T00:00:00+08:00`   : e.end.dateTime, // end.date 係 exclusive
    is_all_day: allDay,
    location: e.location ?? '',
    account_key: ACCOUNT,
    source_calendar: sourceCalendar,
    relevance: 'context',                            // Phase 3 全部用 default，唔派生 linked/noise
    calendar_status: e.status ?? 'confirmed',
    cancelled_at: null,                              // 寫入的行必然 live（Google 有就係存在）
    last_synced_at: cfg.batch_time,
    _updated: e.updated ?? '',                       // 內部欄位，POST 時剝走
  };
}

// 2) 收 Google 事件（SplitOut 後每個 item 一個事件，source_calendar 已 tag 好）
const events = $('SplitOut work events').all().map(i => i.json).filter(e => e?.id);

// nextPageToken guard：截流咗嘅資料唔好拿來 diff（cleanup 會誤標）
if (events.some(e => 'nextPageToken' in e)) {
  return [{ json: { outcome: 'error',
    message: 'work 單日曆事件量超出 maxResults=2500 —— 需要加分頁先可以安全 cleanup' } }];
}

const byCalendar = {};
for (const e of events) byCalendar[e.source_calendar] = (byCalendar[e.source_calendar] ?? 0) + 1;
const gEvents = events.map(e => normalize(e, e.source_calendar));

// 3) DB 現狀（分頁 items 攤平；GET 冇 filter cancelled_at，gate 同 diff 共用）
const dbRows = $('DB GET work').all()
  .flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
const db = new Map(dbRows.map(r => [r.id, r]));

// 4) D3 增量 gate：新事件 / cancelled 重現（無條件重設）/ updated > last_synced_at
const toWrite = gEvents.filter(ev => {
  const d = db.get(ev.id);
  if (!d) return true;                              // INSERT
  if (d.cancelled_at != null) return true;          // 重現 → upsert 帶 cancelled_at:null 重設
  return new Date(ev._updated) > new Date(d.last_synced_at);  // UPDATE；其餘跳過
});

// 5) D2 cleanup diff：DB 窗口內 live ids − Google 返回 ids
const googleIds = new Set(gEvents.map(e => e.id));
const missing = dbRows
  .filter(r => r.cancelled_at == null && !googleIds.has(r.id))
  .map(r => r.id);

// 6) 輸出：rows chunks（500/POST）＋ 一個 cleanup item（missing 同 detail 搭呢件行）
const detail = {
  preset: cfg.preset, window_days: cfg.window_days,
  time_min: cfg.time_min, time_max: cfg.time_max,
  fetched: gEvents.length, by_calendar: byCalendar,
  written: toWrite.length, cancelled: missing.length,
};
const out = [];
for (let i = 0; i < toWrite.length; i += 500) {
  out.push({ json: { rows: toWrite.slice(i, i + 500) } });
}
out.push({ json: { missing, batch_time: cfg.batch_time, detail } });
return out;

// Run Once for All Items — POST 有錯 → 攔住 cleanup（D12 fail-closed）
const mk = $('Marker work');
if (mk.isExecuted) {
  const msg = mk.all().map(i => i.json?.error?.message ?? 'upsert failed').join(' | ');
  return [{ json: { outcome: 'error', message: msg } }];
}
return $input.all();

// Run Once for All Items — missing ids 切 50/chunk（in.() URL 長度限制）
const ids = $json.missing;
const chunks = [];
for (let i = 0; i < ids.length; i += 50) chunks.push(ids.slice(i, i + 50));
return chunks.map(c => ({
  json: {
    idsIn: 'in.(' + c.map(x => `"${x}"`).join(',') + ')',
    batch_time: $json.batch_time,
  },
}));

// Run Once for All Items
// 來源：work「2. 學生相關」嘅 Day 標題事件（design D4：唔讀 personal clone）
const f = $('Flags work');
if (f.isExecuted && f.all().length > 0) return [];   // 上游出錯 → 唔派生（Normalize 會報 error）

const SRC = '2. 學生相關';
const all = $('SplitOut work events').all().map(i => i.json).filter(e => e?.id);
const events = all.filter(e => e.source_calendar === SRC);

// nextPageToken guard：截流咗嘅資料唔好拿來派生
if (events.some(e => 'nextPageToken' in e)) return [];

// design D4 regex：prefix match，全形（U+FF21–FF26）＋半形，大小寫不敏感
const RE = /^\s*day\s*([\uFF21-\uFF26A-Fa-f])/i;

function toHalf(ch) {
  const cp = ch.codePointAt(0);
  return (cp >= 0xff21 && cp <= 0xff26)
    ? String.fromCharCode(cp - 0xfee0)      // 全形 −0xFEE0 → 半形，符合 DB check ^[A-F]$
    : ch.toUpperCase();
}

function hktDate(e) {
  if (e.start?.date) return e.start.date;   // 全日：date 本身就係 HKT 民曆日
  const dt = e.start?.dateTime ?? '';
  return new Date(new Date(dt).getTime() + 8 * 3600000).toISOString().slice(0, 10);
}

const byDate = new Map();
let conflicts = 0;
for (const e of events) {
  const m = RE.exec(e.summary ?? '');
  if (!m) continue;
  const label = toHalf(m[1]);
  if (!/^[A-F]$/.test(label)) continue;     // tripwire：理論上到唔到
  const date = hktDate(e);
  const prev = byDate.get(date);
  if (prev) {
    if (prev.day_label === label) continue;
    conflicts += 1;
    if (new Date(prev._updated) >= new Date(e.updated ?? '')) continue; // 較新嘅事件贏
  }
  byDate.set(date, { date, day_label: label, _updated: e.updated ?? '' });
}

const rows = [...byDate.values()]
  .map(({ _updated, ...r }) => r)
  .sort((a, b) => (a.date < b.date ? -1 : 1));

// tripwire：日曆有 event 但 0 個 Day match → 標題格式/來源異常，寧願 error 都唔靜靜空跑
// （日曆本身 0 events → 合法，靜靜跳過）
if (rows.length === 0 && Object.keys(byCalendarCount(events)).length > 0) {
  throw new Error(`cycle_days：[${SRC}] 有 ${events.length} 個事件但 0 個 Day 標籤 match —— 格式異常`);
}
function byCalendarCount(evts) { return evts.length ? { n: evts.length } : {}; }

return [{ json: { cycle_rows: rows, conflicts, count: rows.length } }];
